}

/**
 * Folds the source label into the target: every issue that carried the source
 * carries the target instead, then the source row is removed. Same permission
 * as deleting a label.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("Cannot merge a label into itself");
  }

  requireFound(
    await labelRepo.findLabel(input.orgId, input.sourceLabelId),
    "Label",
    input.sourceLabelId,
  );
  const target = requireFound(
    await labelRepo.findLabel(input.orgId, input.targetLabelId),
    "Label",
    input.targetLabelId,
  );

  const issuesRelabelled = await labelRepo.mergeLabels(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );

  return { label: target, issuesRelabelled };
}

