export async function deleteLabel(","new_string":"/**
 * Moves every issue assignment from `sourceLabelId` onto `targetLabelId`,
 * then deletes the source label. Issues that already carry the target keep
 * it once. Returns how many issues carried the source label.
 *
 * Callers must reject a source that equals the target before calling this.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  if (sourceLabelId === targetLabelId) {
    throw new Error("Cannot merge a label into itself");
  }

  const db = getDb();
  return db.transaction((tx) => {
    const sourceRows = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all();

    const targetIds = new Set(
      tx
        .select({ issueId: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, targetLabelId),
          ),
        )
        .all()
        .map((row) => row.issueId),
    );

    const overlapping = sourceRows
      .map((row) => row.issueId)
      .filter((issueId) => targetIds.has(issueId));
    const onlySource = sourceRows
      .map((row) => row.issueId)
      .filter((issueId) => !targetIds.has(issueId));

    if (overlapping.length > 0) {
      tx.delete(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
            inArray(issueLabels.issueId, overlapping),
          ),
        )
        .run();
    }

    if (onlySource.length > 0) {
      tx.update(issueLabels)
        .set({ labelId: targetLabelId })
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
            inArray(issueLabels.issueId, onlySource),
          ),
        )
        .run();
    }

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return sourceRows.length;
  });
}

